head.script:
scwin.onpageload = function() {
	requires("uiplugin.popup");
};

scwin.createPopup = function(id, url, top, left, closeAction) {
	var options = {
		id : id,
		type : "wframePopup",
		width : "230px",
		height : "150px",
		top : top + "px",
		left : left + "px",
		popupName : id,
		modal : true,
		useModalStack : true,
		alwaysOnTop : false,
		resizable : true,
		status : true,
		menubar : false,
		scrollbars : false,
		title : false,
		closeAction : closeAction
	};
	scwin.$w.openPopup(url, options);
};

scwin.btnPop_onclick = function(e) {
	scwin.createPopup("popup1", "/sample/common_link/p_popup_useModalStack_WEFF-299_(WSQ-3618)_sub1.xml", 100, 50, "scwin.callback");
};

scwin.callback = function() {
	scwin.createPopup("popup2", "/sample/common_link/p_popup_useModalStack_WEFF-299_(WSQ-3618)_sub2.xml", 100, 150);
	scwin.createPopup("popup3", "/sample/common_link/p_popup_useModalStack_WEFF-299_(WSQ-3618)_sub2.xml", 100, 400);
	scwin.createPopup("popup4", "/sample/common_link/p_popup_useModalStack_WEFF-299_(WSQ-3618)_sub2.xml", 100, 650);
	return true;
};

scwin.checkVal = function() {
	return (document.getElementById('popup3') || document.getElementById('mf_popup3')).style.zIndex != '';
};
